  const items = [{"id":"34","q":"actualizado/34","enlace":"https://somosclave.cl/respuesta.php?q=actualizado/34","nombre":"Plataforma Confirmación y Reagendamiento de Visitas a Terreno"},{"id":"41","q":"actualizado/41","enlace":"https://somosclave.cl/respuesta.php?q=actualizado/41","nombre":"Nuevos Planes Hogar con NETFLIX"},{"id":"65","q":"actualizado/65","enlace":"https://somosclave.cl/respuesta.php?q=actualizado/65","nombre":"ELIMINACIÓN DE APLICACIONES NO OFICIALES PLAY STORE"},{"id":"67","q":"actualizado/67","enlace":"https://somosclave.cl/respuesta.php?q=actualizado/67","nombre":"Procedimiento Anulación Venta Móvil Mercado Empresarial"},{"id":"75","q":"actualizado/75","enlace":"https://somosclave.cl/respuesta.php?q=actualizado/75","nombre":"Suscripción Pago Automático PAC/PAT"}];
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = [];
  for (const it of items) {
    const row = await new Promise((resolve) => {
      const ifr = document.createElement('iframe');
      ifr.style.cssText = 'position:fixed;left:-9999px;width:900px;height:700px;opacity:0;pointer-events:none';
      ifr.src = 'https://somosclave.cl/respuesta.php?q=' + it.q;
      document.body.appendChild(ifr);
      const t0 = Date.now();
      const timer = setInterval(() => {
        try {
          const doc = ifr.contentDocument;
          const faq = doc && doc.querySelector('#faq-content');
          if (faq && faq.innerHTML.length > 200) {
            clearInterval(timer);
            resolve({
              id: it.id,
              q: it.q,
              enlace: it.enlace,
              categoriaPath: (it.q || '').split('/')[0] || 'actualizado',
              title: (doc.querySelector('#faq-title')?.innerText || it.nombre || '').trim(),
              html: faq.innerHTML,
              ok: true,
            });
            ifr.remove();
          } else if (Date.now() - t0 > 14000) {
            clearInterval(timer);
            resolve({ id: it.id, q: it.q, ok: false, err: 'timeout', html: '', title: '' });
            ifr.remove();
          }
        } catch (e) {
          if (Date.now() - t0 > 14000) {
            clearInterval(timer);
            resolve({ id: it.id, ok: false, err: String((e && e.message) || e), html: '', title: '' });
            ifr.remove();
          }
        }
      }, 350);
    });
    out.push(row);
    await wait(100);
  }
  return out;
})()
